//! The clean tier's skater and board.
//!
//! The skater is a CC0 MakeHuman character with our own body shape, rig names and animation set,
//! generated by `scripts/cleanroom/blender/make_skater.py` (clips authored in `skater_anims.py`)
//! into `assets/skater.glb`. Every clip is driven by hand each frame: its time comes from the
//! engine's state (crouch, push phase, flip progress, time since the pop or landing) and its weight
//! from the mode, eased so transitions blend. The board is built in code.
use super::sim::CleanSkate;
use bevy::prelude::*;
use skate_lite_sys::{EventKind, Mode, State};
use std::f32::consts::FRAC_PI_2;

pub(crate) const DECK_TOP: f32 = 0.105;
const DECK_LEN: f32 = 0.8;
const DECK_WIDTH: f32 = 0.205;
const DECK_THICK: f32 = 0.013;
const KICK_LEN: f32 = 0.13;
const KICK_ANGLE: f32 = 0.33;
const WHEEL_R: f32 = 0.027;
const AXLE_Z: f32 = 0.235;
pub(crate) const DECK_CENTRE: f32 = 0.09;
/// Ankle height above the sole in the authored clips.
pub(crate) const ANKLE: f32 = 0.075;
/// Where the pop clip reaches its full extension (the flip clips start from that pose).
const POP_TOP_AT: f32 = 0.1;
/// Tail snap on the pop: peak nose-up pitch (radians), when it peaks and when it is level again.
const POP_PITCH: f32 = 0.34;
const POP_PITCH_PEAK: f32 = 0.05;
const POP_PITCH_END: f32 = 0.24;

const SKATER_GLB: &str = "embedded://skate_game/clean/assets/skater.glb";

/// Clips in the order of [`CLIP_NAMES`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(usize)]
enum Clip {
    Ride,
    Crouch,
    Pop,
    Air,
    FlipKick,
    FlipHeel,
    FlipShuv,
    Land,
    Push,
    Manual,
    NoseManual,
    Grind,
    Boardslide,
    Powerslide,
    Bail,
    PushEnd,
    // One per grab style, in sk8_grab_style order (style n is GRAB_FIRST + n - 1).
    GrabIndy,
    GrabCrail,
    GrabTail,
    GrabStalefish,
    GrabMelon,
    GrabNose,
    GrabTuckKnee,
    GrabJudo,
    GrabDouble,
    GrabSuperman,
    GrabNoFoot,
    GrabStiffy,
}

const CLIPS: usize = 28;
const GRAB_FIRST: usize = Clip::GrabIndy as usize;
pub(crate) const CLIP_NAMES: [&str; CLIPS] = [
    "sk8_ride", "sk8_crouch", "sk8_pop", "sk8_air", "sk8_flip_kick", "sk8_flip_heel", "sk8_flip_shuv", "sk8_land", "sk8_push", "sk8_manual",
    "sk8_nose_manual", "sk8_grind", "sk8_boardslide", "sk8_powerslide", "sk8_bail", "sk8_push_end",
    "sk8_grab_indy", "sk8_grab_crail", "sk8_grab_tail", "sk8_grab_stalefish", "sk8_grab_melon", "sk8_grab_nose",
    "sk8_grab_tuck_knee", "sk8_grab_judo", "sk8_grab_double", "sk8_grab_superman", "sk8_grab_no_foot", "sk8_grab_stiffy",
];
/// Clips that loop (idles and the push); the rest play once and hold their last frame.
const LOOPED: [Clip; 8] =
    [Clip::Ride, Clip::Crouch, Clip::Push, Clip::Manual, Clip::NoseManual, Clip::Grind, Clip::Boardslide, Clip::Powerslide];

#[derive(Component)]
pub(crate) struct RiderRoot;
#[derive(Component)]
pub(crate) struct BoardRoot;

#[derive(Resource)]
pub(crate) struct Avatar {
    gltf: Handle<Gltf>,
    nodes: Option<Vec<AnimationNodeIndex>>,
    player: Option<Entity>,
    /// Each clip's length as exported (s), so timing follows the authored clips.
    lens: [f32; CLIPS],
    pub(crate) bones: Option<super::procedural::Bones>,
    pub(crate) weights: [f32; CLIPS],
    weight_vel: [f32; CLIPS],
    /// Each clip's time; a clip fading out holds where it was instead of jumping to its start.
    pub(crate) times: [f32; CLIPS],
}

pub(crate) fn spawn(
    mut commands: Commands,
    assets: Res<AssetServer>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
) {
    let rider = commands
        .spawn((RiderRoot, Transform::default(), Visibility::default()))
        .id();
    // The clips face -Y in Blender (= +Z here) with the nose along +X; the engine's
    // board has its nose along +Z, so the character turns a quarter about Y.
    let scene = commands
        .spawn((
            SceneRoot(assets.load(GltfAssetLabel::Scene(0).from_asset(SKATER_GLB))),
            Transform::from_rotation(Quat::from_rotation_y(-FRAC_PI_2)),
        ))
        .id();
    commands.entity(rider).add_child(scene);
    commands.insert_resource(Avatar {
        gltf: assets.load(SKATER_GLB),
        nodes: None,
        player: None,
        lens: [1.0; CLIPS],
        bones: None,
        weights: [0.0; CLIPS],
        weight_vel: [0.0; CLIPS],
        times: [0.0; CLIPS],
    });

    let mat = |m: &mut Assets<StandardMaterial>, c: Color, rough: f32, metal: f32| {
        m.add(StandardMaterial {
            base_color: c,
            perceptual_roughness: rough,
            metallic: metal,
            ..default()
        })
    };
    let deck = mat(&mut materials, Color::srgb(0.86, 0.62, 0.3), 0.6, 0.0);
    let grip = mat(&mut materials, Color::srgb(0.06, 0.06, 0.07), 0.95, 0.0);
    let metal = mat(&mut materials, Color::srgb(0.72, 0.73, 0.76), 0.35, 0.9);
    let urethane = mat(&mut materials, Color::srgb(0.95, 0.93, 0.86), 0.5, 0.0);
    // Board: root at the deck centre so flips turn about it.
    let board = commands
        .spawn((BoardRoot, Transform::default(), Visibility::default()))
        .id();
    let mut piece = |mesh: Mesh, material: &Handle<StandardMaterial>, t: Transform| {
        let child = commands
            .spawn((Mesh3d(meshes.add(mesh)), MeshMaterial3d(material.clone()), t))
            .id();
        commands.entity(board).add_child(child);
    };
    let flat = DECK_LEN - 2.0 * KICK_LEN;
    let y = DECK_TOP - DECK_CENTRE - DECK_THICK * 0.5;
    piece(Cuboid::new(DECK_WIDTH, DECK_THICK, flat).into(), &deck, Transform::from_xyz(0.0, y, 0.0));
    piece(
        Cuboid::new(DECK_WIDTH * 0.98, 0.002, flat).into(),
        &grip,
        Transform::from_xyz(0.0, y + DECK_THICK * 0.5 + 0.001, 0.0),
    );
    for end in [1.0f32, -1.0] {
        let hinge = Vec3::new(0.0, y, end * flat * 0.5);
        let rot = Quat::from_rotation_x(-end * KICK_ANGLE);
        let centre = hinge + rot * Vec3::new(0.0, 0.0, end * KICK_LEN * 0.5);
        piece(
            Cuboid::new(DECK_WIDTH * 0.96, DECK_THICK, KICK_LEN).into(),
            &deck,
            Transform::from_translation(centre).with_rotation(rot),
        );
        piece(
            Cuboid::new(DECK_WIDTH * 0.96, 0.002, KICK_LEN).into(),
            &grip,
            Transform::from_translation(centre + rot * Vec3::Y * (DECK_THICK * 0.5 + 0.001)).with_rotation(rot),
        );
        let axle = WHEEL_R - DECK_CENTRE;
        piece(
            Cuboid::new(0.16, 0.03, 0.045).into(),
            &metal,
            Transform::from_xyz(0.0, (axle + y) * 0.5, end * AXLE_Z),
        );
        for x in [-1.0f32, 1.0] {
            piece(
                Cylinder::new(WHEEL_R, 0.032).mesh().resolution(20).into(),
                &urethane,
                Transform::from_xyz(x * 0.085, axle, end * AXLE_Z).with_rotation(Quat::from_rotation_z(FRAC_PI_2)),
            );
        }
    }
}

/// Once the glTF is in: one animation graph with every clip, on the scene's player.
pub(crate) fn bind(
    mut commands: Commands,
    mut avatar: ResMut<Avatar>,
    gltfs: Res<Assets<Gltf>>,
    anims: Res<Assets<AnimationClip>>,
    mut graphs: ResMut<Assets<AnimationGraph>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
    players: Query<Entity, Added<AnimationPlayer>>,
    names: Query<(Entity, &Name)>,
) {
    if avatar.nodes.is_some() {
        return;
    }
    let (Some(gltf), Ok(player)) = (gltfs.get(&avatar.gltf), players.single()) else { return };
    let clips: Vec<Handle<AnimationClip>> = CLIP_NAMES
        .iter()
        .map(|n| gltf.named_animations.get(*n).cloned().unwrap_or_else(|| {
            warn!("SK8 avatar: clip {n} missing");
            Handle::default()
        }))
        .collect();
    for (len, clip) in avatar.lens.iter_mut().zip(&clips) {
        if let Some(c) = anims.get(clip) {
            *len = c.duration().max(1e-3);
        }
    }
    let (graph, nodes) = AnimationGraph::from_clips(clips);
    // MakeHuman materials arrive alpha-blended, which sorts badly (skin shows through the
    // clothes); cut-out alpha keeps hair and lashes and draws everything else opaque.
    for handle in &gltf.materials {
        if let Some(m) = materials.get_mut(handle) {
            m.alpha_mode = AlphaMode::Mask(0.5);
        }
    }
    commands.entity(player).insert(AnimationGraphHandle(graphs.add(graph)));
    avatar.bones = super::procedural::Bones::find(&names);
    if avatar.bones.is_none() {
        warn!("SK8 avatar: bones for the procedural layer missing");
    }
    info!("SK8 avatar bound: {} clips, lengths {:?}", nodes.len(), avatar.lens);
    avatar.nodes = Some(nodes);
    avatar.player = Some(player);
}

#[derive(Resource)]
pub(crate) struct Clock {
    pub(crate) since_pop: f32,
    since_land: f32,
    since_grab: f32,
    /// Since the last kick ended (the back foot steps back on and the front foot turns back).
    since_push: f32,
    /// Drives the idle loops (ride sway, manual and grind balance).
    idle: f32,
}

impl Default for Clock {
    fn default() -> Self {
        // Long ago, so nothing plays its "just happened" clip at spawn.
        Self { since_pop: 9.0, since_land: 9.0, since_grab: 0.0, since_push: 9.0, idle: 0.0 }
    }
}

/// Which way the front foot leaves the board for this trick.
fn flip_clip(trick: &str) -> Clip {
    let t = trick.to_ascii_lowercase();
    if t.contains("heel") || t.contains("laser") {
        Clip::FlipHeel
    } else if t.contains("flip") || t.contains("hardflip") {
        Clip::FlipKick
    } else {
        Clip::FlipShuv
    }
}

/// How long a blend into this clip takes (smoothing time of a critically damped follow, s):
/// the pop and catch are quick, body shifts like settling into a push or a manual slower.
fn blend_time(clip: Clip) -> f32 {
    match clip {
        Clip::Pop => 0.035,
        Clip::FlipKick | Clip::FlipHeel | Clip::FlipShuv => 0.05,
        Clip::Land | Clip::Bail => 0.05,
        Clip::Air | Clip::Grind | Clip::Boardslide => 0.08,
        Clip::GrabIndy
        | Clip::GrabCrail
        | Clip::GrabTail
        | Clip::GrabStalefish
        | Clip::GrabMelon
        | Clip::GrabNose
        | Clip::GrabTuckKnee
        | Clip::GrabJudo
        | Clip::GrabDouble
        | Clip::GrabSuperman
        | Clip::GrabNoFoot
        | Clip::GrabStiffy
        | Clip::Manual | Clip::NoseManual | Clip::Powerslide => 0.1,
        Clip::Ride | Clip::Crouch => 0.13,
        // The front foot turns ~100 degrees to point down the board: not in a snap.
        Clip::Push => 0.2,
        Clip::PushEnd => 0.12,
    }
}

/// (target weight, time) per clip for this state; `None` time = the clip is not playing.
fn targets(s: &State, c: &Clock, trick: &str, len: &[f32; CLIPS]) -> [(f32, Option<f32>); CLIPS] {
    let mut t = [(0.0, None); CLIPS];
    let mut set = |clip: Clip, w: f32, time: f32| {
        let l = len[clip as usize];
        let time = if LOOPED.contains(&clip) { time.rem_euclid(l) } else { time.clamp(0.0, l) };
        t[clip as usize] = (w, Some(time));
    };
    let pop_len = len[Clip::Pop as usize];
    match s.mode {
        Mode::Bail => set(Clip::Bail, 1.0, s.bail_time.unwrap_or(0.0)),
        Mode::Grind if s.grind_kind == 2 => set(Clip::Boardslide, 1.0, c.idle),
        Mode::Grind => set(Clip::Grind, 1.0, c.idle),
        Mode::Manual if s.manual_dir < 0 => set(Clip::NoseManual, 1.0, c.idle),
        Mode::Manual => set(Clip::Manual, 1.0, c.idle),
        Mode::Slide => set(Clip::Powerslide, 1.0, c.idle),
        Mode::Air => {
            // A flip takes over from the pop at full extension, where its clip starts.
            let pop_until = if s.flip_progress.is_some() { POP_TOP_AT } else { pop_len };
            if c.since_pop < pop_until {
                set(Clip::Pop, 1.0, c.since_pop);
            } else if let Some(p) = s.flip_progress {
                let clip = flip_clip(trick);
                set(clip, 1.0, p * len[clip as usize]);
            } else if s.grab != 0 {
                // The engine's grab style picks the clip; an unknown one falls back by hand.
                let style = match s.grab_style as usize {
                    n @ 1..=12 => n,
                    _ if s.grab == 3 => 9,
                    _ if s.grab & 1 != 0 => 5,
                    _ => 1,
                };
                set(CLIP_ORDER[GRAB_FIRST + style - 1], 1.0, c.since_grab);
            } else {
                // Tuck, hold, then reach the legs down for the landing.
                set(Clip::Air, 1.0, c.since_pop - pop_len);
            }
        }
        Mode::Ride => {
            if c.since_land < len[Clip::Land as usize] {
                set(Clip::Land, 1.0, c.since_land);
            } else if let Some(phase) = s.push_phase {
                set(Clip::Push, 1.0, phase * len[Clip::Push as usize]);
            } else if c.since_push < len[Clip::PushEnd as usize] {
                set(Clip::PushEnd, 1.0, c.since_push);
            } else {
                set(Clip::Ride, 1.0 - s.crouch, c.idle);
                set(Clip::Crouch, s.crouch, c.idle);
            }
        }
    }
    t
}

#[allow(clippy::type_complexity)]
pub(crate) fn animate(
    time: Res<Time<Real>>,
    sim: Res<CleanSkate>,
    mut avatar: ResMut<Avatar>,
    mut clock: ResMut<Clock>,
    mut players: Query<&mut AnimationPlayer>,
    mut rider: Query<&mut Transform, With<RiderRoot>>,
) {
    let dt = time.delta_secs().min(0.1);
    let (a, b, t) = (&sim.previous, &sim.current, sim.alpha());
    let pos = Vec3::from_array(a.position).lerp(Vec3::from_array(b.position), t);
    let rider_rot = Quat::from_array(a.rider_rot).slerp(Quat::from_array(b.rider_rot), t);
    let up = rider_rot * Vec3::Y;

    let game_dt = if sim.paused { 0.0 } else { dt * sim.time_scale };
    clock.since_pop += game_dt;
    clock.since_land += game_dt;
    clock.since_push = if b.push_phase.is_some() { 0.0 } else { clock.since_push + game_dt };
    clock.since_grab = if b.grab != 0 { clock.since_grab + game_dt } else { 0.0 };
    // The idles quicken a little with speed.
    clock.idle += game_dt * (0.7 + 0.3 * (b.speed / 6.0).min(1.0));
    for e in &sim.events {
        match e.kind {
            EventKind::Pop => clock.since_pop = 0.0,
            EventKind::Land => clock.since_land = 0.0,
            _ => {}
        }
    }

    let rider_at = pos + up * DECK_TOP;
    if let Ok(mut tf) = rider.single_mut() {
        *tf = Transform::from_translation(rider_at).with_rotation(rider_rot);
    }

    // Clip weights and times. Every weight follows its goal with a critically damped spring (eased
    // in and out, never overshooting), all at the pace of the clip being blended in.
    let goals = targets(b, &clock, &sim.rider.trick(), &avatar.lens);
    let lead = (0..CLIPS).max_by(|&i, &j| goals[i].0.total_cmp(&goals[j].0)).unwrap_or(0);
    let smooth = blend_time(CLIP_ORDER[lead]);
    // A respawn is a cut: no standing up out of the bail in front of the camera.
    if sim.events.iter().any(|e| e.kind == EventKind::Respawn) {
        for i in 0..CLIPS {
            avatar.weights[i] = goals[i].0;
            avatar.weight_vel[i] = 0.0;
        }
    }
    for i in 0..CLIPS {
        let (w, v) = smooth_cd(avatar.weights[i], avatar.weight_vel[i], goals[i].0, smooth, dt);
        avatar.weights[i] = w.clamp(0.0, 1.0);
        avatar.weight_vel[i] = v;
        if let Some(time) = goals[i].1 {
            avatar.times[i] = time;
        }
    }
    let total: f32 = avatar.weights.iter().sum::<f32>().max(1e-4);
    if let (Some(nodes), Some(player)) = (avatar.nodes.clone(), avatar.player) {
        if let Ok(mut player) = players.get_mut(player) {
            for (i, node) in nodes.iter().enumerate() {
                let weight = avatar.weights[i] / total;
                if !player.is_playing_animation(*node) {
                    player.play(*node).pause();
                }
                if let Some(active) = player.animation_mut(*node) {
                    active.set_weight(weight);
                    if weight > 1e-3 {
                        active.seek_to(avatar.times[i]);
                    }
                }
            }
        }
    }
}

/// The pop's tail snap: the tail slams down and the nose comes up, pivoting on the tail wheels,
/// then the front foot levels it out. Returns the board's shift and its turned rotation.
pub(crate) fn pop_snap(deck: Quat, since_pop: f32) -> (Vec3, Quat) {
    if since_pop >= POP_PITCH_END {
        return (Vec3::ZERO, deck);
    }
    let k = if since_pop < POP_PITCH_PEAK {
        smooth01(since_pop / POP_PITCH_PEAK)
    } else {
        1.0 - smooth01((since_pop - POP_PITCH_PEAK) / (POP_PITCH_END - POP_PITCH_PEAK))
    };
    let pitch = Quat::from_rotation_x(-POP_PITCH * k);
    let tail = Vec3::new(0.0, WHEEL_R - DECK_CENTRE, -AXLE_Z);
    (deck * (tail - pitch * tail), deck * pitch)
}

const CLIP_ORDER: [Clip; CLIPS] = [
    Clip::Ride, Clip::Crouch, Clip::Pop, Clip::Air, Clip::FlipKick, Clip::FlipHeel, Clip::FlipShuv, Clip::Land, Clip::Push,
    Clip::Manual, Clip::NoseManual, Clip::Grind, Clip::Boardslide, Clip::Powerslide, Clip::Bail, Clip::PushEnd,
    Clip::GrabIndy, Clip::GrabCrail, Clip::GrabTail, Clip::GrabStalefish, Clip::GrabMelon, Clip::GrabNose, Clip::GrabTuckKnee,
    Clip::GrabJudo, Clip::GrabDouble, Clip::GrabSuperman, Clip::GrabNoFoot, Clip::GrabStiffy,
];

fn smooth01(x: f32) -> f32 {
    let x = x.clamp(0.0, 1.0);
    x * x * (3.0 - 2.0 * x)
}

/// One step of a critically damped follow of `target` (smoothing time `smooth`, s): stable for
/// any frame time, so the blends look the same at 60, 72 or 90 Hz.
pub(crate) fn smooth_cd(value: f32, vel: f32, target: f32, smooth: f32, dt: f32) -> (f32, f32) {
    let omega = 2.0 / smooth.max(1e-3);
    let x = omega * dt;
    let decay = 1.0 / (1.0 + x + 0.48 * x * x + 0.235 * x * x * x);
    let change = value - target;
    let temp = (vel + omega * change) * dt;
    ((target + (change + temp) * decay), (vel - omega * temp) * decay)
}
